<form class="panel" method="post" action="/admin/webinars/save" enctype="multipart/form-data" style="max-width:940px"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) ($w['id'] ?? 0) ?>"><div class="panel-b form">
<div class="row2"><?= a_in('Title', 'title', $w['title'] ?? '', ['required' => true]) ?><?= a_sel('Format', 'kind', ['webinar' => 'Webinar (presenter-led)', 'workshop' => 'Workshop', 'meeting' => 'Meeting'], $w['kind'] ?? 'webinar') ?></div>
<?= a_in('One-line summary', 'summary', $w['summary'] ?? '') ?>
<div class="row3"><?= a_in('Starts', 'start_at', !empty($w['start_at']) ? date('Y-m-d\TH:i', strtotime($w['start_at'])) : '', ['type' => 'datetime-local', 'required' => true, 'hint' => 'Kenya time (EAT). Attendees see it in their own time zone.']) ?><?= a_in('Duration (minutes)', 'duration_min', $w['duration_min'] ?? 60, ['type' => 'number', 'min' => 10]) ?><?= a_in('Seats', 'capacity', $w['capacity'] ?? 100, ['type' => 'number', 'min' => 2]) ?></div>
<div class="row3"><?= a_in('Price (KSh, 0 = free)', 'price', $w['price'] ?? 0, ['type' => 'number', 'min' => 0]) ?><?= a_sel('Who can join', 'access', ['registered' => 'Registered attendees (personal links)', 'public' => 'Anyone with the link'], $w['access'] ?? 'registered') ?><?= a_sel('Status', 'status', ['draft' => 'Draft (hidden)', 'scheduled' => 'Scheduled (public)', 'cancelled' => 'Cancelled', 'ended' => 'Ended'], $w['status'] ?? 'draft') ?></div>
<?php if (is_super()): ?><div class="row2"><?= a_sel('Host account', 'host_id', ['' => 'Me'] + array_column($hosts, 'name', 'id'), $w['host_id'] ?? '') ?><?= a_in('Host name shown publicly', 'host_name', $w['host_name'] ?? '') ?></div><?php endif; ?>
<?= a_in('Description', 'description', $w['description'] ?? '', ['type' => 'textarea', 'rows' => 6]) ?><?= a_in('Agenda', 'agenda', $w['agenda'] ?? '', ['type' => 'textarea', 'rows' => 4, 'hint' => 'Use “- ” bullets. Example: - 3:00 Welcome']) ?>
<?= a_in('Speakers (one per line: Name | Title)', 'speakers', $speakers, ['type' => 'textarea', 'rows' => 3]) ?>
<div class="row2"><div class="field"><label for="f-cover">Cover photo</label><input id="f-cover" type="file" name="cover" accept="image/*"><?php if (!empty($w['cover'])): ?><img src="<?= e(img_url($w['cover'])) ?>" alt="" style="margin-top:8px;max-width:220px;border-radius:10px"><span class="hint">Current photo. Choose a new file to replace it.</span><?php else: ?><span class="hint">JPG, PNG or WebP. Large phone photos are resized automatically.</span><?php endif; ?></div><?= a_in('Recording link (YouTube, Vimeo or .mp4)', 'recording_url', $w['recording_url'] ?? '') ?></div>
<?= a_sel('Delivery mode', 'engine', ['builtin' => 'Interactive room — everyone connects browser-to-browser (best up to ~25 people, no extra server)', 'broadcast' => 'Broadcast — 100+ viewers and live streaming to social media (needs the media server)'], $w['engine'] ?? 'builtin', media_enabled() ? 'Media server connected.' : 'The media server is not connected yet — set it up under Live → Streaming first. Until then Broadcast falls back to the interactive room.') ?>
<div class="row3"><?= a_check('Waiting room (admit people manually)', 'waiting_room', $w['waiting_room'] ?? 0) ?><?= a_check('Live chat enabled', 'chat_enabled', $w['chat_enabled'] ?? 1) ?><?= a_check('Q&A enabled', 'qa_enabled', $w['qa_enabled'] ?? 1) ?></div><?= a_check('Make the replay public once the session has ended', 'replay_public', $w['replay_public'] ?? 0) ?>
<div style="display:flex;gap:10px"><button class="btn btn-primary">Save session</button><a class="btn btn-ghost" href="/admin/webinars">Cancel</a></div></div></form>
